/**
 * Regex builder on every search box. In regex mode the visible lists and tables on the page filter live; pressing
 * Enter still runs the normal Moodle search with the text as typed.
 *
 * @module     theme_material/searchbars
 * @copyright  2026 Ding Ding Projects
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define('theme_material/searchbars', [], function() {
    var s = {};
    var SELECTOR = 'input[type="search"], .simplesearchform input[type="text"], input[name="search"], input[name="q"], ' +
        'input[name="query"], input[data-region="search-input"], input[data-action="search"], .search-input-wrapper input';
    var ITEMS = '#region-main table tbody tr, #region-main .list-group-item, #region-main .activity-item, ' +
        '#region-main [data-region="course-content"] .card, #region-main .coursebox, #region-main .dashboard-card, ' +
        '#region-main [data-region="paged-content-page"] li, #region-main .forumpost, #region-main .course-listitem';
    var GLYPH = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" ' +
        'stroke-linecap="round" aria-hidden="true"><path d="M5 20 13 4"/><path d="M17 4v8M13.6 6l6.8 4M13.6 10l6.8-4"/>' +
        '<circle cx="5.5" cy="17.5" r="1.4" fill="currentColor" stroke="none"/></svg>';
    var BLOCKS = [['^', 'blockstartswith'], ['$', 'blockendswith'], ['.*', 'blockanything'], ['\\d', 'blockdigit'],
        ['[A-Za-z]', 'blockletter'], ['\\b', 'blockwordedge'], ['\\s', 'blockspace'], ['+', 'blockoneormore'],
        ['?', 'blockoptional'], ['|', 'blockeither']];

    /**
     * Filter the page's lists with the pattern.
     *
     * @param {string} q
     * @param {boolean} ignoreCase
     * @param {HTMLElement} status
     */
    function filter(q, ignoreCase, status) {
        var re = null;
        if (q) {
            try {
                re = new RegExp(q, ignoreCase ? 'i' : '');
            } catch (e) {
                status.textContent = s.patternincomplete;
                status.classList.add('is-invalid');
                return;
            }
        }
        status.classList.remove('is-invalid');
        var shown = 0;
        var total = 0;
        document.querySelectorAll(ITEMS).forEach(function(item) {
            total++;
            var hit = !re || re.test(item.textContent.replace(/\s+/g, ' '));
            if (hit) {
                shown++;
                if (item.dataset.mdFiltered) {
                    item.hidden = false;
                    delete item.dataset.mdFiltered;
                }
            } else if (!item.hidden) {
                item.hidden = true;
                item.dataset.mdFiltered = '1';
            }
        });
        status.textContent = q ? shown + ' / ' + total + ' ' + (s.matches || '') : '';
    }

    /**
     * Attach the builder to one search box.
     *
     * @param {HTMLInputElement} input
     */
    function attach(input) {
        if (input.dataset.mdRegex || input.closest('.md-palette, .md-regex-pop')) {
            return;
        }
        input.dataset.mdRegex = '1';
        var state = {on: false, ignoreCase: true};
        var group = input.closest('.input-group, .search-input-wrapper') || input.parentNode;
        var toggle = document.createElement('button');
        toggle.type = 'button';
        toggle.className = 'md-regex-toggle';
        toggle.setAttribute('aria-pressed', 'false');
        toggle.setAttribute('aria-expanded', 'false');
        toggle.setAttribute('aria-label', s.regexbuilder);
        toggle.title = s.regexbuilder;
        toggle.innerHTML = GLYPH + '<span class="md-regex-toggle-label"></span><span class="md-regex-toggle-dot" aria-hidden="true"></span>';
        toggle.querySelector('.md-regex-toggle-label').textContent = s.useregex || 'Regex';
        var pop = document.createElement('div');
        pop.className = 'md-regex md-regex-pop';
        pop.hidden = true;
        var head = document.createElement('div');
        head.className = 'md-regex-head';
        var h = document.createElement('h2');
        h.textContent = s.regexbuilder;
        var mode = document.createElement('button');
        mode.type = 'button';
        mode.className = 'md-chip';
        mode.textContent = s.useregex;
        mode.setAttribute('aria-pressed', 'false');
        var ci = document.createElement('button');
        ci.type = 'button';
        ci.className = 'md-chip';
        ci.textContent = s.ignorecase;
        ci.setAttribute('aria-pressed', 'true');
        var row = document.createElement('div');
        row.className = 'md-chip-row';
        row.appendChild(mode);
        row.appendChild(ci);
        head.appendChild(h);
        head.appendChild(row);
        var blocks = document.createElement('div');
        blocks.className = 'md-chip-row';
        BLOCKS.forEach(function(b) {
            var chip = document.createElement('button');
            chip.type = 'button';
            chip.className = 'md-chip is-block';
            chip.innerHTML = '<code></code> ';
            chip.querySelector('code').textContent = b[0];
            chip.appendChild(document.createTextNode(s[b[1]] || b[1]));
            chip.addEventListener('click', function() {
                input.value += b[0];
                if (!state.on) {
                    mode.click();
                }
                run();
                input.focus();
            });
            blocks.appendChild(chip);
        });
        var status = document.createElement('span');
        status.className = 'md-regex-status';
        status.setAttribute('aria-live', 'polite');
        pop.appendChild(head);
        pop.appendChild(blocks);
        pop.appendChild(status);
        var run = function() {
            if (state.on) {
                filter(input.value, state.ignoreCase, status);
            } else {
                filter('', true, status);
            }
        };
        mode.addEventListener('click', function() {
            state.on = !state.on;
            mode.setAttribute('aria-pressed', state.on ? 'true' : 'false');
            run();
        });
        ci.addEventListener('click', function() {
            state.ignoreCase = !state.ignoreCase;
            ci.setAttribute('aria-pressed', state.ignoreCase ? 'true' : 'false');
            run();
        });
        var sync = function() {
            toggle.setAttribute('aria-pressed', state.on ? 'true' : 'false');
            toggle.setAttribute('aria-expanded', pop.hidden ? 'false' : 'true');
            toggle.classList.toggle('is-on', state.on);
            group.classList.toggle('md-regex-active', state.on);
        };
        toggle.addEventListener('click', function() {
            if (!state.on) {
                mode.click();
                pop.hidden = false;
            } else if (pop.hidden) {
                pop.hidden = false;
            } else {
                mode.click();
                pop.hidden = true;
            }
            sync();
            input.focus();
        });
        mode.addEventListener('click', function() {
            sync();
        });
        input.addEventListener('input', run);
        var host = input.closest('.simplesearchform, form') || group.parentNode;
        // The toggle sits inside the field as a trailing button.
        var wrap = document.createElement('span');
        wrap.className = 'md-regex-field';
        input.parentNode.insertBefore(wrap, input);
        wrap.appendChild(input);
        wrap.appendChild(toggle);
        // Place the builder below the field, outside any row layout, so it pushes content down instead of overlapping.
        var anchor = host;
        while (anchor.parentNode && anchor.parentNode !== document.body &&
                /flex|grid/.test(window.getComputedStyle(anchor.parentNode).display) &&
                window.getComputedStyle(anchor.parentNode).flexDirection !== 'column') {
            anchor = anchor.parentNode;
        }
        anchor.parentNode.insertBefore(pop, anchor.nextSibling);
    }

    return {
        /**
         * Start, and keep attaching to search boxes added later.
         *
         * @param {Object} strings
         */
        init: function(strings) {
            s = strings || {};
            document.querySelectorAll(SELECTOR).forEach(attach);
            new MutationObserver(function() {
                document.querySelectorAll(SELECTOR).forEach(attach);
            }).observe(document.body, {childList: true, subtree: true});
        }
    };
});
